// Constant pool to tablica przechowujaca WSZYSTKIE literaly, nazwy klas/metod/pol i sygnatury
// typow uzywane w danej klasie - kazdy z tych elementow jest zapisany TYLKO RAZ, a reszta
// pliku .class odwoluje sie do niego przez numer INDEKSU (np. instrukcja bajtkodu
// 'invokevirtual #7' oznacza 'wywolaj metode opisana we wpisie #7 constant poola').
// Przyklad wpisu: literal String "Witaj swiecie" uzyty w System.out.println("Witaj swiecie")
// trafia do constant poola jako osobny wpis typu CONSTANT_String.

Path workDir = Files.createTempDirectory("ex06");
Files.writeString(workDir.resolve("Add.java"), "public class Add { public static void main(String[] a) { System.out.println(3 + 4); } }");
String javaHome = System.getProperty("java.home");
String javac = javaHome + File.separator + "bin" + File.separator + "javac";
String java = javaHome + File.separator + "bin" + File.separator + "java";

new ProcessBuilder(javac, workDir.resolve("Add.java").toString()).inheritIO().start().waitFor(10, java.util.concurrent.TimeUnit.SECONDS);
ProcessBuilder runPb = new ProcessBuilder(java, "-cp", workDir.toString(), "Add");
runPb.inheritIO();
runPb.start().waitFor(10, java.util.concurrent.TimeUnit.SECONDS);

// Maszyna STOSOWA (jak JVM) wykonuje operacje poprzez wrzucanie i zdejmowanie wartosci
// z jednego, wspolnego STOSU OPERANDOW - instrukcja 'iadd' po prostu zdejmuje dwie gorne
// wartosci ze stosu, dodaje je i wklada wynik z powrotem, bez odwolania do konkretnych
// 'miejsc pamieci'. Maszyna REJESTROWA (jak typowy fizyczny CPU x86/ARM) operuje na
// SKONCZONYM zbiorze nazwanych rejestrow (np. EAX, EBX) - instrukcje jawnie okreslaja,
// KTORE rejestry sa zrodlem/celem operacji. Bajtkod stosowy jest prostszy do wygenerowania
// przez kompilator i bardziej kompaktowy, ale wymaga dodatkowej translacji (przez JIT)
// na instrukcje rejestrowe faktycznie wykonywane przez CPU.

Path workDir = Files.createTempDirectory("ex09");
Path src = workDir.resolve("Broken.java");
Files.writeString(src, "public class Broken { public static void main(String[] a) { int x = 5 } }"); // brak srednika
JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
int result = compiler.run(null, System.out, System.err, "-d", workDir.toString(), src.toString());
System.out.println("Kod wyjscia (oczekiwane != 0): " + result);

System.out.println("iconst_0/iconst_1 - wrzuca maly staly int na stos");
System.out.println("istore_N - zapisuje int ze stosu do lokalnej zmiennej N");
System.out.println("iload_N - wczytuje int z lokalnej zmiennej N na stos");
System.out.println("imul - mnozy dwie wartosci int ze stosu");
System.out.println("iadd - dodaje dwie wartosci int ze stosu");
System.out.println("if_icmpgt - warunkowy skok przy porownaniu dwoch intow");
System.out.println("goto - bezwarunkowy skok");
System.out.println("invokevirtual - wywoluje metode instancji z polimorfizmem");
System.out.println("invokespecial - wywoluje konstruktor/metode prywatna, bez polimorfizmu");

String source = "public class Factorial { public static void main(String[] a) { int n=5, r=1, i=1; while (i <= n) { r *= i; i++; } System.out.println(r); } }";
// Skompiluj, uruchom javap -c, output zawiera np. 'if_icmpgt' (koniec petli gdy i > n)
// i 'goto' (powrot na poczatek petli) - to instrukcje sterujace przeplywem petli while.

// static int add1(int a, int b) { return a + b; }         // iload_0, iload_1, iadd, ireturn - 4 instrukcje
// static int add2(int a, int b) { return Math.addExact(a, b); } // iload_0, iload_1, invokestatic, ireturn - 4 instrukcje
// Wniosek: liczba instrukcji jest podobna, ale add2 zawiera invokestatic (wywolanie metody)
// zamiast prostej instrukcji iadd - to potencjalnie WOLNIEJSZE (choc JIT moze zinline'owac).

// class Overloaded { void m(int x) {} void m(String s) {} }
// javap -s wypisze deskryptory: 'descriptor: (I)V' dla m(int) i 'descriptor: (Ljava/lang/String;)V' dla m(String)
// (I)V oznacza: metoda przyjmuje JEDEN argument typu int ('I'), zwraca void ('V') -
// deskryptory kodują typy jako litery (I=int, J=long, Z=boolean, L...;=typ referencyjny).

long smallSize = Files.size(classesDir.resolve("Small.class"));
long bigSize = Files.size(classesDir.resolve("Big.class"));
System.out.println("Small.class: " + smallSize + " B");
System.out.println("Big.class: " + bigSize + " B");
System.out.println("Roznica: " + (bigSize - smallSize) + " B");

// class Demo { public void pub() {} private void priv() {} }
// javap Demo.class (bez flag) domyslnie wypisze TYLKO metode 'pub()' - metoda 'priv()' NIE
// pojawi sie w outpucie, bo domyslny poziom widocznosci javap to 'public/protected'.
// Aby zobaczyc TAKZE prywatne metody, trzeba uzyc flagi -p (javap -p Demo.class).

// String source = "class Concat { static String f(int x) { return \"a\" + x + \"b\"; } }";
// javap -c pokaze m.in.: 'invokedynamic #N, makeConcatWithConstants:(I)Ljava/lang/String;'
// Nowoczesny javac (od Java 9, JEP 280) NIE generuje juz recznie StringBuilder.append(...)
// dla konkatenacji '+' - zamiast tego uzywa invokedynamic laczacego sie w runtime z
// StringConcatFactory, ktora dynamicznie dobiera najbardziej efektywna strategie konkatenacji.

compiler.run(null, System.out, System.err, "-d", outWithDebug.toString(), "-g", src.toString());
compiler.run(null, System.out, System.err, "-d", outNoDebug.toString(), "-g:none", src.toString());
long withDebug = Files.size(outWithDebug.resolve("Demo.class"));
long noDebug = Files.size(outNoDebug.resolve("Demo.class"));
System.out.println("Z -g: " + withDebug + " B, z -g:none: " + noDebug + " B, roznica: " + (withDebug - noDebug) + " B");

// javap -l Demo.class wypisze sekcje 'LineNumberTable:' z wpisami w stylu:
// line 3: 0
// line 4: 4
// line 5: 9
// Kazdy wpis mapuje OFFSET bajtkodu (np. '0', '4', '9') na numer linii zrodla ('line 3'..) -
// to wlasnie ta tabela pozwala JVM wygenerowac dokladny numer linii w stack trace wyjatku.

// interface Demo { void abstractMethod(); default void defaultMethod() { System.out.println("default"); } }
// javap -c Demo.class pokaze:
// - dla abstractMethod(): BRAK sekcji z instrukcjami (metoda nie ma ciala - deklaracja only)
// - dla defaultMethod(): REALNE instrukcje bajtkodu (getstatic, ldc, invokevirtual, return),
//   bo metoda default MA konkretna implementacje skompilowana do bajtkodu, w odroznieniu
//   od abstrakcyjnej, ktora jest tylko deklaracja kontraktu.

// static int sumFor() { int s = 0; for (int i = 1; i <= 10; i++) s += i; return s; }
// static int sumWhile() { int s = 0; int i = 1; while (i <= 10) { s += i; i++; } return i; }
// Wniosek po porownaniu javap -c: bajtkod OBU metod jest PRAKTYCZNIE IDENTYCZNY -
// for i while to tylko roznica SKLADNIOWA na poziomie zrodla, kompilator generuje ten
// sam wzorzec instrukcji (inicjalizacja, warunek, cialo, inkrementacja, skok).

static String compileAndDisassemble(String className, String sourceCode) throws Exception {
    Path workDir = Files.createTempDirectory("disasm");
    Path src = workDir.resolve(className + ".java");
    Files.writeString(src, sourceCode);
    ToolProvider.getSystemJavaCompiler().run(null, System.out, System.err, "-d", workDir.toString(), "-g", src.toString());
    String javap = System.getProperty("java.home") + File.separator + "bin" + File.separator + "javap";
    ProcessBuilder pb = new ProcessBuilder(javap, "-c", "-v", "-cp", workDir.toString(), className);
    pb.redirectErrorStream(true);
    Process p = pb.start();
    String output = new String(p.getInputStream().readAllBytes());
    p.waitFor(10, java.util.concurrent.TimeUnit.SECONDS);
    return output;
}

System.out.println(compileAndDisassemble("A", "public class A { public static void main(String[] a) {} }"));
System.out.println(compileAndDisassemble("B", "public class B { int x = 5; }"));

// Przetworz output javap -c: kazda linia w stylu '     3: iadd' to JEDNA instrukcja bajtkodu.
// Grupuj linie po naglowkach metod (linie konczace sie na '{'), licz instrukcje w kazdej grupie,
// posortuj Map<String, Integer> malejaco po wartosci i wypisz jako ranking.

// static int factorial(int n) { return n <= 1 ? 1 : n * factorial(n - 1); }
// javap -c -v pokaze linie: 'invokestatic #N // Method factorial:(I)I' - metoda 'Method
// factorial:(I)I' w komentarzu javap to DOWOD, ze bajtkod tej metody wywoluje SAMA SIEBIE
// (nazwa i sygnatura w constant poolu wskazuja na te sama metode factorial).

// static int sumArray(int[] arr) { int s = 0; for (int x : arr) s += x; return s; }
// static int sumList(List<Integer> list) { int s = 0; for (Integer x : list) s += x.intValue(); return s; }
// Wersja z int[] uzywa prostych 'iaload'/'iadd'. Wersja z List<Integer> DODATKOWO zawiera
// 'invokevirtual Integer.intValue' (rozpakowanie Integer -> int) - to widoczny koszt
// autoboxingu w bajtkodzie.

byte[] bytes = Files.readAllBytes(classesDir.resolve("Demo.class"));
StringBuilder hex = new StringBuilder();
for (int i = 0; i < 8; i++) {
    hex.append(String.format("%02x ", bytes[i] & 0xFF));
}
System.out.println(hex.toString().trim()); // ca fe ba be 00 00 00 41 (np. 0x41=65 dla Javy 21)

compiler.run(null, System.out, System.err, "-d", out17.toString(), "--release", "17", src.toString());
compiler.run(null, System.out, System.err, "-d", out21.toString(), "--release", "21", src.toString());
// javap -v na obu plikach .class pokaze rozne 'major version':
// --release 17 -> major version: 61
// --release 21 -> major version: 65

// String source = "class S { static String f(int x) { return switch (x) { case 1 -> \"jeden\"; case 2 -> \"dwa\"; default -> \"?\"; }; } }"
// javap -c pokaze 'tableswitch' (bo wartosci 1,2 sa GESTE, sekwencyjne) - kompilator generuje
// TABLICE SKOKOW indeksowana bezposrednio wartoscia (O(1)). Dla RZADKICH wartosci (np. case 1,
// 1000, 100000) kompilator wygenerowalby 'lookupswitch' - wyszukiwanie binarne po posortowanej
// liscie wartosci (O(log n)) zamiast marnowac pamiec na ogromna, rzadka tablice skokow.

Map<String, Integer> freq = new HashMap<>();
for (String line : javapOutput.split("\n")) {
    String trimmed = line.trim();
    if (trimmed.matches("\\d+:.*")) {
        String instr = trimmed.split(":")[1].trim().split("\\s+")[0];
        freq.merge(instr, 1, Integer::sum);
    }
}
freq.entrySet().stream()
    .sorted(Map.Entry.<String,Integer>comparingByValue().reversed())
    .forEach(e -> System.out.println(e.getKey() + ": " + e.getValue() + " razy"));

// static void demo() { try { int x = 1 / 0; } catch (ArithmeticException e) { System.out.println("blad"); } }
// javap -c -v pokaze sekcje 'Exception table:' z kolumnami:
// from    to  target type
//     0     4     7   Class java/lang/ArithmeticException
// 'from'/'to' to zakres OFFSETOW bajtkodu (instrukcje w bloku try), 'target' to offset,
// do ktorego JVM SKACZE gdy wystapi wyjatek tego typu (poczatek bloku catch), a 'type' to
// KLASA wyjatku, dla ktorej ten wpis jest aktywny (referencja do constant poola).

static void analyzeClass(String className, String source) throws Exception {
    String output = compileAndDisassemble(className, source); // z Zadania 21
    output.lines().filter(l -> l.contains("major version") || l.contains("minor version"))
        .forEach(System.out::println);
    long constantPoolEntries = output.lines().filter(l -> l.trim().matches("#\\d+.*")).count();
    System.out.println("Wpisy constant pool: " + constantPoolEntries);
    output.lines().filter(l -> l.trim().startsWith("public ") || l.trim().startsWith("private "))
        .forEach(l -> System.out.println("Metoda: " + l.trim()));
}

analyzeClass("MultiMethod", "public class MultiMethod { public void a() {} private void b() {} public static void main(String[] x) {} }");
